func policiesInOrder(cp ConnectionPolicies, a, b []int) iter.Seq[*ConnectionPolicy] {
	return func(yield func(*ConnectionPolicy) bool) {
		for len(a) > 0 || len(b) > 0 {
			var i int
			if len(b) == 0 || (len(a) > 0 && a[0] < b[0]) {
				i, a = a[0], a[1:]
			} else {
				i, b = b[0], b[1:]
			}
			if !yield(cp[i]) {
				return
			}
		}
	}
}

